16	// DEVDESK-473: the route stage keeps every lookup it made on its check, so the
17	// path trace can reuse the reading instead of asking the routing table again.
18	// These tests pin what is kept; the stage's verdicts, summary and facts are
19	// pinned by stage_route_test.go and by the golden test at the end of this file.
20	
21	// countingRoute wraps a per-address answer and counts the calls it receives.
22	type countingRoute struct {
23		mu    sync.Mutex
24		calls []string
25		reply func(ip net.IP) (RouteHop, error)
26	}
27	
28	func (c *countingRoute) route(_ context.Context, ip net.IP) (RouteHop, error) {
29		c.mu.Lock()
30		c.calls = append(c.calls, ip.String())
31		c.mu.Unlock()
32		return c.reply(ip)
33	}
34	
35	func (c *countingRoute) seen() []string {
36		c.mu.Lock()
37		defer c.mu.Unlock()
38		return append([]string(nil), c.calls...)
39	}
