41	// lookupHop is a distinct hop per interface name, so a lookup can be told apart
42	// from another one.
43	func lookupHop(iface, source, gateway string) RouteHop {
44		h := RouteHop{Interface: iface, Source: net.ParseIP(source)}
45		if gateway != "" {
46			h.Gateway = net.ParseIP(gateway)
47		}
48		return h
49	}
50	
51	func sameHop(a, b RouteHop) bool {
52		return a.Interface == b.Interface && a.Source.Equal(b.Source) && a.Gateway.Equal(b.Gateway)
53	}
