55	// TestRouteStageKeepsOneLookupPerAddressInOrder covers (a), (b) and (c): a
56	// routed address keeps its hop, a proven no-route and an undetermined lookup
57	// keep their error untouched, and several addresses give one entry each, in the
58	// order they were asked.
59	func TestRouteStageKeepsOneLookupPerAddressInOrder(t *testing.T) {
60		const (
61			a = "93.184.216.34"
62			b = "93.184.216.35"
63			c = "2606:2800:220:1::1"
64		)
65		hopA := lookupHop("eth0", "192.168.1.21", "192.168.1.1")
66		hopB := lookupHop("wg0", "10.2.0.2", "")
67		enetunreach := fmt.Errorf("lookup %s: %w", c, syscall.ENETUNREACH)
68		generic := errors.New("routing table unreadable")
69	
70		type reply struct {
71			hop RouteHop
72			err error
73		}
74		tests := []struct {
75			name    string
76			ips     []string
77			replies map[string]reply
78			// wantNoRoute is the set of addresses whose kept error must satisfy
79			// nettrace.IsNoRoute.
80			wantNoRoute map[string]bool
81		}{
82			{
83				name:    "one routed address keeps its hop and no error",
84				ips:     []string{a},
85				replies: map[string]reply{a: {hop: hopA}},
86			},
87			{
88				name:        "a proven no-route keeps its error",
89				ips:         []string{c},
90				replies:     map[string]reply{c: {err: enetunreach}},
91				wantNoRoute: map[string]bool{c: true},
92			},
93			{
94				name:    "an undetermined lookup keeps its error and is not a proof",
95				ips:     []string{a},
96				replies: map[string]reply{a: {err: generic}},
97			},
98			{
99				name: "three addresses give three entries in the order asked",
100				ips:  []string{b, c, a},
101				replies: map[string]reply{
102					b: {hop: hopB},
103					c: {err: enetunreach},
104					a: {err: generic},
105				},
106				wantNoRoute: map[string]bool{c: true},
107			},
108			{
109				name: "two routed addresses keep their own hop each",
110				ips:  []string{a, b},
111				replies: map[string]reply{
112					a: {hop: hopA},
113					b: {hop: hopB},
114				},
115			},
116		}
117	
118		for _, tc := range tests {
119			t.Run(tc.name, func(t *testing.T) {
120				env := fakeEnv{route: func(_ context.Context, ip net.IP) (RouteHop, error) {
121					r := tc.replies[ip.String()]
122					return r.hop, r.err
123				}}
124				var ips []net.IP
125				for _, s := range tc.ips {
126					ips = append(ips, net.ParseIP(s))
127				}
128				prior := resolvedTo(t, ips...)
129	
130				check := routeCheck(t, env, target(), prior)
131				fromRun := RunStep(context.Background(), target(), env, DefaultSettings(), StageRoute, prior).RouteLookups()
132	
133				for name, got := range map[string][]RouteLookup{
134					"Check.Routes":           check.Routes,
135					"Results.RouteLookups()": fromRun,
136				} {
137					if len(got) != len(tc.ips) {
138						t.Fatalf("%s has %d entries, want %d (one per address, in order): %v",
139							name, len(got), len(tc.ips), got)
140					}
141					for i, want := range tc.ips {
142						l := got[i]
143						if l.IP.String() != want {
144							t.Errorf("%s[%d].IP = %v, want %s", name, i, l.IP, want)
145						}
146						r := tc.replies[want]
147						if !sameHop(l.Hop, r.hop) {
148							t.Errorf("%s[%d].Hop = %+v, want %+v", name, i, l.Hop, r.hop)
149						}
150						if !errors.Is(l.Err, r.err) && l.Err != r.err {
151							t.Errorf("%s[%d].Err = %v, want %v untouched", name, i, l.Err, r.err)
152						}
153						if r.err == nil && l.Err != nil {
154							t.Errorf("%s[%d].Err = %v, want nil for a routed address", name, i, l.Err)
155						}
156						if r.err != nil && l.Err == nil {
157							t.Errorf("%s[%d].Err = nil, want the lookup's error", name, i)
158						}
159						if l.Err != nil && nettrace.IsNoRoute(l.Err) != tc.wantNoRoute[want] {
160							t.Errorf("%s[%d]: IsNoRoute(%v) = %v, want %v", name, i, l.Err,
161								nettrace.IsNoRoute(l.Err), tc.wantNoRoute[want])
162						}
163					}
164				}
165			})
166		}
167	}
