169	// TestRouteStageCallsRouteOncePerAddress pins AC5 (the number of readings is
170	// unchanged) and the cap: with ten addresses, eight are asked and eight are
171	// kept, neither more nor fewer.
172	func TestRouteStageCallsRouteOncePerAddress(t *testing.T) {
173		tests := []struct {
174			name  string
175			count int
176			want  int
177		}{
178			{"one address", 1, 1},
179			{"three addresses", 3, 3},
180			{"exactly the cap", maxRoutedAddresses, maxRoutedAddresses},
181			{"ten addresses are capped at the lookup limit", 10, maxRoutedAddresses},
182		}
183		for _, tc := range tests {
184			t.Run(tc.name, func(t *testing.T) {
185				counter := &countingRoute{reply: func(net.IP) (RouteHop, error) {
186					return lookupHop("eth0", "192.168.1.21", "192.168.1.1"), nil
187				}}
188				var ips []net.IP
189				for i := 0; i < tc.count; i++ {
190					ips = append(ips, net.IPv4(93, 184, 216, byte(i+1)))
191				}
192	
193				check := routeCheck(t, fakeEnv{route: counter.route}, target(), resolvedTo(t, ips...))
194	
195				if got := len(counter.seen()); got != tc.want {
196					t.Fatalf("env.Route called %d times, want %d", got, tc.want)
197				}
198				if len(check.Routes) != tc.want {
199					t.Fatalf("Check.Routes has %d entries, want %d", len(check.Routes), tc.want)
200				}
201				for i, l := range check.Routes {
202					if l.IP.String() != counter.seen()[i] {
203						t.Errorf("Routes[%d].IP = %v, want the %dth address asked (%s)", i, l.IP, i+1, counter.seen()[i])
204					}
205				}
206			})
207		}
208	}
