270	// TestRouteLookupsReturnsACopy keeps a reader from changing what the results
271	// hold: the slice it gets is its own.
272	func TestRouteLookupsReturnsACopy(t *testing.T) {
273		env := fakeEnv{route: func(_ context.Context, ip net.IP) (RouteHop, error) {
274			return lookupHop("eth0", "192.168.1.21", "192.168.1.1"), nil
275		}}
276		res := RunStep(context.Background(), target(), env, DefaultSettings(), StageRoute,
277			resolvedTo(t, net.ParseIP("93.184.216.34"), net.ParseIP("93.184.216.35")))
278	
279		first := res.RouteLookups()
280		if len(first) != 2 {
281			t.Fatalf("RouteLookups() has %d entries, want 2", len(first))
282		}
283		first[0] = RouteLookup{IP: net.ParseIP("10.0.0.1"), Err: errors.New("changed by a reader")}
284	
285		again := res.RouteLookups()
286		if len(again) != 2 {
287			t.Fatalf("after a reader changed its copy, RouteLookups() has %d entries, want 2", len(again))
288		}
289		if again[0].IP.String() != "93.184.216.34" || again[0].Err != nil {
290			t.Fatalf("after a reader overwrote its copy, RouteLookups()[0] = %+v, want the original lookup", again[0])
291		}
292	}
